  ((select id from w), 'recall', 'Fill in the missing phrase: what did Jesus say he would make Simon and Andrew into, in Mark 1:17?', 'Mark 1:17', 'Jesus said to them, ''Come after me, and I will make you into fishers for men.''', 'WEB', 1,
   '{"type": "recall", "template": "Jesus said to them, ''Come after me, and I will make you into ___.''", "answer": "fishers for men"}', false, 4),
  ((select id from w), 'multiple_choice', 'According to Mark 1:22, how did the people say Jesus taught, unlike the scribes?', 'Mark 1:22', 'They were astonished at his teaching, for he taught them as having authority, and not as the scribes.', 'WEB', 2,
