  ((select id from w), 'recall', 'Fill in the missing word: according to Mark 1:34, why didn''t Jesus allow the demons he cast out to speak?', 'Mark 1:34', 'He healed many who were sick with various diseases and cast out many demons. He didn''t allow the demons to speak, because they knew him.', 'WEB', 2,
