  ((select id from w), 'multiple_choice', 'According to Mark 1:35, what did Jesus do early in the morning, while it was still dark?', 'Mark 1:35', 'Early in the morning, while it was still dark, he rose up and went out, and departed into a deserted place, and prayed there.', 'WEB', 1,
