  ((select id from w), 'recall', 'Fill in the missing word: what did Jesus tell the paralytic in Mark 2:5, seeing the faith of the men who lowered him?', 'Mark 2:5', 'Jesus, seeing their faith, said to the paralytic, ''Son, your sins are forgiven you.''', 'WEB', 1,
   '{"type": "recall", "template": "Jesus, seeing their faith, said to the paralytic, ''Son, your sins are ___ you.''", "answer": "forgiven"}', false, 8),
  ((select id from w), 'recall', 'Fill in the missing word: in Mark 2:9-10, what does Jesus say the Son of Man has authority on earth to forgive?', 'Mark 2:9-10', 'Which is easier, to tell the paralytic, ''Your sins are forgiven;'' or to say, ''Arise, and take up your bed, and walk''? But that you may know that the Son of Man has authority on earth to forgive sins', 'WEB', 3,
