  ((select id from w), 'multiple_choice', 'According to Mark 2:12, what did the crowd say after the paralyzed man got up and walked out carrying his mat?', 'Mark 2:12', 'He arose, and immediately took up the mat and went out in front of them all, so that they were all amazed and glorified God, saying, ''We never saw anything like this!''', 'WEB', 2,
