  ((select id from w), 'recall', 'Fill in the missing word: what did Jairus ask Jesus to do for his dying daughter, in Mark 5:23?', 'Mark 5:23', 'My little daughter is at the point of death. Please come and lay your hands on her, that she may be made healthy, and live.', 'WEB', 1,
