  ((select id from w), 'recall', 'Fill in the missing word: what did the woman with the flow of blood say to herself, in Mark 5:27-28?', 'Mark 5:27-28', 'having heard the things concerning Jesus, came up behind him in the crowd and touched his clothes. For she said, ''If I just touch his clothes, I will be made well.''', 'WEB', 2,
