  ((select id from w), 'recall', 'Fill in the missing phrase: what did the voice from the cloud tell the disciples to do, in Mark 9:7?', 'Mark 9:7', 'A cloud came, overshadowing them, and a voice came out of the cloud, ''This is my beloved Son. Listen to him.''', 'WEB', 2,
