  ((select id from w), 'recall', 'Fill in the missing word: what did the crowds shout as Jesus entered Jerusalem, in Mark 11:9-10?', 'Mark 11:9-10', 'Those who went in front and those who followed cried out, ''Hosanna! Blessed is he who comes in the name of the Lord! Blessed is the kingdom of our father David that is coming in the name of the Lord! Hosanna in the highest!''', 'WEB', 1,
