  ((select id from w), 'recall', 'Fill in the missing word: according to Mark 15:34, what did Jesus cry out from the cross, in Aramaic and its translation?', 'Mark 15:34', 'At the ninth hour Jesus cried with a loud voice, saying, ''Eloi, Eloi, lama sabachthani?'' which is, being interpreted, ''My God, my God, why have you forsaken me?''', 'WEB', 2,
