  ((select id from w), 'multiple_choice', 'According to Mark 16:8, why did the women say nothing to anyone after fleeing the tomb?', 'Mark 16:8', 'They went out, and fled from the tomb, for trembling and astonishment had come on them. They said nothing to anyone; for they were afraid.', 'WEB', 2,
